(() => {
  'use strict';
  const M=WorkoutModel,KEY='barbell_workout_v3',TEMPLATES='barbell_templates_v3',HISTORY='barbell_workout_history_v3';
  const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  let w=null,view='home',editor=null,busy=false,photoURL='',wake=null,awake=false,beeped=false,syncingCompetition=false,competitionSyncQueued=false;
  const get=(k,f)=>{try{return JSON.parse(localStorage.getItem(k)||JSON.stringify(f));}catch{return f;}};
  const put=(k,v)=>{localStorage.setItem(k,JSON.stringify(v));CloudBackup.changed();};
  function save(){put(KEY,w);updateStatus();}
  function remember(e){const details=get('barbell_lift_details_v3',{});details[e.id]={structure:e.structure,workoutId:e.workoutId||'',notes:e.notes};put('barbell_lift_details_v3',details);}
  const root=()=>document.getElementById('training-root');
  function fail(e){showToast(e.message||'Could not save. Keep this screen open.','error');}
  function field(label,control,help=''){return `<label class="studio-field"><span>${label}</span>${control}${help?`<small>${help}</small>`:''}</label>`;}
  const button=(text,act,extra='',kind='secondary')=>`<button type="button" class="studio-${kind}" data-act="${act}" ${extra}>${text}</button>`;
  function options(items,value){return items.map(x=>`<option value="${esc(x.value??x)}" ${(x.value??x)===value?'selected':''}>${esc(x.label??x)}</option>`).join('');}
  const sessions=selected=>`<select data-w="session">${options([{value:'Coached Class',label:'Class'},{value:'1:1 Session',label:'1:1'},{value:'Solo',label:'Solo'}],M.session(selected))}</select>`;
  function refs(b){b.referenceLift=M.reference(b);const r=TrainingCore.findReference(b.referenceLift,getCachedEntries(),loadSettings().pbs||[]);b.reference=r.weight||'';return b;}
  const loadingHint=()=>w.loading==='competition'?'Whole kilos · 20 kg bar + 5 kg collars. Session type stays unchanged.':'20 kg bar · weights matched to your gym plates.';
  const headingTitle=workout=>workout.type==='opener'?'Opener rehearsal':M.sessionLabel(workout.session)+' session';
  function refreshTitle(){const el=root()?.querySelector('[data-title]');if(el&&w)el.textContent=headingTitle(w);}
  function load(){w=M.migrate(get(KEY,null)||get('barbell_training_v2',null));if(w)localStorage.setItem(KEY,JSON.stringify(w));if(!localStorage.getItem(TEMPLATES))put(TEMPLATES,get('barbell_workout_templates_v2',[]).map(M.migrate).filter(Boolean));if(!localStorage.getItem(HISTORY))put(HISTORY,get('barbell_training_history_v2',[]).map(M.migrate).filter(Boolean));}
  function competitionSource(){const comp=loadSettings().comp||{},attempts={'Snatch':getCompetitionAttempts('snatch'),'Clean and Jerk':getCompetitionAttempts('cj')};return{date:comp.date||'',name:comp.name||'Competition plan',attempts,signature:JSON.stringify([comp.date||'',comp.name||'',attempts])};}
  function reconcileCompetition(){if(syncingCompetition||!w?.competitionLink||w.type!=='opener'||w.phase==='finished')return false;syncingCompetition=true;try{const source=competitionSource(),link=w.competitionLink;if(link.signature===source.signature)return false;try{if(link.date&&source.date!==link.date)throw Error('Competition changed. Pull the current plan to link this rehearsal to it.');const next=M.syncOpenerPlan(w,source.attempts);next.competitionLink={...link,date:link.date||source.date,name:source.name,signature:source.signature,status:'linked'};w=next;}catch(e){w.competitionLink={...link,signature:source.signature,status:e.message};}save();return true;}finally{syncingCompetition=false;}}
  function linkCompetition(){const source=competitionSource(),next=M.syncOpenerPlan(w,source.attempts);next.competitionLink={date:source.date,name:source.name,signature:source.signature,status:'linked'};w=next;save();render();}
  function competitionLinkHTML(){const link=w.competitionLink;return `<div class="rehearsal-link"><p><strong>${link?'Linked to '+esc(link.name):'Competition plan'}</strong></p>${link?`<p>${link.status==='linked'?'Upcoming attempts follow your plan; recorded sets stay unchanged.':esc(link.status)}</p><div class="rehearsal-link-actions">${button('Edit competition plan','open-comp-plan')}${link.status!=='linked'?button('Use current plan','link-plan'):''}${button('Unlink','unlink-plan','','quiet')}</div>`:button('Use competition plan','link-plan','','wide')}</div>`;}
  function queueCompetitionSync(){if(syncingCompetition||!w?.competitionLink)return;const focused=document.activeElement;if(root()?.contains(focused)&&focused.matches('input,select,textarea')){competitionSyncQueued=true;return;}competitionSyncQueued=false;if(reconcileCompetition()&&view==='workout'&&document.getElementById('pane-planner').classList.contains('active'))render();}
  function open(){if(window.AccessoryApp?.isOpen())AccessoryApp.close();switchTab('planner',document.querySelectorAll('#tabs .tab')[1]);render();document.getElementById('pane-planner').scrollTop=0;}
  function archiveDraft(){if(w&&w.phase!=='finished'&&w.blocks?.length)put(HISTORY,[M.copy(w),...get(HISTORY,[]).filter(x=>x.id!==w.id)]);}
  function create(type){archiveDraft();w=M.blank(type);view='workout';save();render();top();}
  function top(){document.getElementById('pane-planner').scrollTop=0;}
  function render(){reconcileCompetition();if(window.AccessoryApp?.isOpen()){AccessoryApp.render();return;}const el=root();if(!el)return;el.hidden=false;document.getElementById('accessory-root')?.setAttribute('hidden','');if(view==='home'||!w){el.innerHTML=homeHTML();bind(el);return;}
    el.innerHTML=`<div class="studio-heading"><div><span class="eyebrow">${w.phase==='active'?'IN PROGRESS':w.phase==='finished'?'COMPLETE':'BUILD YOUR SESSION'}</span><h2 data-title>${esc(headingTitle(w))}</h2></div>${button('Switch','switch')}</div>`+(w.competitionLink&&w.competitionLink.status!=='linked'?`<p class="studio-status" role="status">${esc(w.competitionLink.status)}</p>`:'')+(w.phase==='setup'?setupHTML():w.phase==='active'?activeHTML():finishedHTML());bind(el);clock();updateStatus();}
  function homeHTML(){const templates=get(TEMPLATES,[]),saved=get(HISTORY,[]),history=saved.filter(x=>x.phase==='finished'),drafts=saved.filter(x=>x.phase!=='finished'&&x.id!==w?.id);return `<div class="studio-intro"><h2>What’s the session?</h2><p>Build today’s movements, then let the app handle the numbers.</p></div>
    ${w?`<section class="studio-card"><strong>${esc(M.title(w))}</strong><p>${Object.keys(w.done||{}).length} recorded sets · ${w.phase}</p>${button(w.phase==='finished'?'View summary':'Resume session','resume','','primary')}</section>`:''}
    <div class="studio-choices">${button('<strong>Class</strong><span>Start blank. Add the program from today’s board.</span>','new-class')}${button('<strong>1:1</strong><span>Log a lesson afterwards, or build a session.</span>','lesson')}${button('<strong>Solo</strong><span>Build your own workout.</span>','new-solo')}${button('<strong>Opener rehearsal</strong><span>Plan attempts, warm-ups, loading and rest.</span>','opener')}${button('<strong>Accessories</strong><span>Start a saved workout, build your own, or log it afterwards.</span>','accessory')}${button('<strong>Photo / paste a program</strong><span>Read a photo into an editable transcription.</span>','import')}</div>
    <section class="studio-section"><h3>Your templates</h3><p>Save any plan as a template. Open or delete it here.</p>${templates.length?templates.map(t=>`<div class="studio-template"><div><strong>${esc(t.templateName||t.blocks.map(M.sequence).join(' / '))}</strong><small>${M.sessionLabel(t.session)} · ${t.blocks.length} blocks</small></div>${button('Open','template-open',`data-id="${t.id}"`)}${button('Delete','template-delete',`data-id="${t.id}"`,'quiet')}</div>`).join(''):'<p class="studio-muted">No saved templates yet.</p>'}</section>
    ${drafts.length?`<section class="studio-section"><h3>Other saved drafts</h3>${drafts.map(x=>`<div class="studio-template"><div><strong>${esc(M.title(x))}</strong><small>${Object.keys(x.done||{}).length} recorded sets</small></div>${button('Resume','resume-draft',`data-id="${x.id}"`)}</div>`).join('')}</section>`:''}
    ${history.length?`<section class="studio-section"><h3>Recent sessions</h3>${history.slice(0,5).map(x=>`<div class="studio-template"><div><strong>${esc(M.title(x))}</strong><small>${Object.keys(x.done||{}).length} sets</small></div>${button('Repeat','history',`data-id="${x.id}"`)}</div>`).join('')}</section>`:''}
    <p class="studio-backup" data-cloud-status></p>`;}
  function setupHTML(){return `<section class="studio-card studio-session-card"><div class="studio-grid studio-session-fields">${field('Date',`<input type="date" data-w="date" value="${w.date}">`)}${w.type==='opener'?'':field('Session',sessions(w.session))}</div>
    ${w.type==='opener'?'<p class="studio-muted">Competition loading · recorded as Solo</p>':field('Loading',`<select data-w="loading">${options([{value:'gym',label:'Gym plates'},{value:'competition',label:'Competition'}],w.loading)}</select>`,loadingHint())}${w.type==='opener'?competitionLinkHTML():''}</section>
    ${!w.blocks.length?'<div class="studio-empty-plan"><h3>Add your first lift</h3><p>Choose a movement, add modifiers, then combine movements if it’s a complex.</p></div>':''}
    ${w.blocks.map((b,i)=>blockHTML(b,i)).join('')}${w.type==='opener'?'':button(w.blocks.length?'+ Add another lift / complex':'+ Add a lift / complex','add-block','',w.blocks.length?'wide':'primary wide')}
    <div class="studio-footer-actions">${w.blocks.length?button('Start session','start','','primary wide')+button('Save as template','template-save','','wide'):''}${button('Leave / discard draft','exit','','quiet wide')}</div>
    <details class="studio-details studio-builder-help"><summary>Warm-up & rest guidance</summary><p class="studio-muted">Bar first, then roughly 40%, 55%, 70% and 85% of the top working weight. Steps at or above your first working set are skipped. Rehearsals build towards the opener. Loads match your selected plates.</p>${w.type==='opener'?'<p class="studio-muted">Rehearsals use your chosen recovery between heavier lifts, including before the opener. Actual competition timing follows the running order; adjust the gap with your coach.</p>':'<p class="studio-muted">Up to 50% of your reference: no timed rest. Then 45s, 75s, and 120s as the load increases. Short blocks reduce rest, with 30s minimum above 50%. These are editable suggestions with your two-minute timer cap; heavy lifting can call for longer recovery.</p>'}<a href="https://www.catalystathletics.com/article/1878/A-Simple-Guide-to-Weightlifting-Competition-Warm-ups/" target="_blank" rel="noopener">Competition warm-up guidance</a></details><p class="studio-backup" data-cloud-status></p>`;}
  function componentHTML(c,bid,index,total,context='workout'){
    const cfg=LIFT_CONFIG[c.base]||{};const extra=`data-b="${bid}" data-c="${c.id}" data-context="${context}"`;
    const groups=[['technique','Squat type',cfg.squat_types||[]],['position','Start position',cfg.positions||[]],['receiving','Receiving',c.base==='Squat'?[]:cfg.receiving||[]],['grip','Grip',cfg.grip||[]],['technique','Technique',(cfg.technique||[]).filter(t=>!['Complex','2-Position'].includes(t))]];
    return `<article class="studio-component"><div class="studio-component-top"><span>Movement ${index+1}</span><div>${index?button('↑','component-up',extra,'quiet'):''}${index<total-1?button('↓','component-down',extra,'quiet'):''}${button('Duplicate','component-copy',extra,'quiet')}${total>1?button('×','component-remove',extra+' aria-label="Remove movement"','quiet'):''}</div></div>
      ${field('Base movement',`<select data-comp="base" ${extra}>${options(M.bases,c.base)}</select>`)}${c.base==='Other'?field('Movement name',`<input data-comp="name" ${extra} value="${esc(c.name||'')}">`):''}
      ${groups.filter(g=>g[2].length).map(([key,label,values])=>`<div class="studio-mod-group"><span>${label}</span><div class="studio-chips">${values.filter(v=>v!=='Hang (unspecified)').map(v=>{const selected=key==='receiving'?c.receiving===v:(c[key]||[]).includes(v);return `<button type="button" class="studio-chip ${selected?'selected':''}" data-act="modifier" ${extra} data-group="${key}" data-value="${esc(v)}" aria-pressed="${selected}">${esc(v==='Squat (Full)'?'Squat':v)}</button>`;}).join('')}</div></div>`).join('')}
      <div class="studio-sequence-name">${esc(M.name(c))}</div></article>`;
  }
  function rehearsalHTML(b,i){return `<section class="studio-card rehearsal-block" data-block="${b.id}"><div class="studio-block-title"><span class="block-letter">${String.fromCharCode(65+i)}</span><h3>${b.components[0]?.base==='Snatch'?'Snatch':'Clean & jerk'}</h3></div><p class="studio-muted">Competition movement · build-up based on your opener</p>${[1,2,3].map(attempt=>{const stage=b.stages.find(s=>s.attempt===attempt);return field(['Opener (kg)','Proposed second (kg, optional)','Proposed third (kg, optional)'][attempt-1],`<input type="number" min="26" step="1" inputmode="numeric" data-rehearsal-attempt="${attempt}" data-b="${b.id}" ${w.competitionLink?'readonly':''} value="${stage?esc(stage.value):''}">`);}).join('')}${field('Recovery between heavier lifts (minutes)',`<input type="number" data-rehearsal-rest="${b.id}" min="1" max="10" step="0.5" value="${(b.restSeconds||180)/60}">`,'Includes the gap from your final warm-up to the opener. Adjust to a routine you have rehearsed.')}${field('Build-up',`<select data-block-field="warmups" data-b="${b.id}"><option value="yes" ${b.warmups?'selected':''}>Include warm-ups</option><option value="no" ${!b.warmups?'selected':''}>Attempts only</option></select>`)}<div class="studio-preview" data-preview="${b.id}">${previewHTML(b)}</div></section>`;}
  function blockHTML(b,i){if(b.rehearsal)return rehearsalHTML(b,i);return `<section class="studio-card" data-block="${b.id}"><div class="studio-block-title"><span class="block-letter">${String.fromCharCode(65+i)}</span><h3>${esc(M.sequence(b))}</h3>${button('Remove','remove-block',`data-b="${b.id}" aria-label="Remove block"`,'quiet')}</div>
    ${b.components.map((c,n)=>componentHTML(c,b.id,n,b.components.length)).join('<div class="studio-plus">then +</div>')}${button('+ Add movement to complex','component-add',`data-b="${b.id}"`,'wide')}
    <div class="studio-grid">${field('Percentages based on',`<select data-block-field="referenceLift" data-b="${b.id}">${options(['Snatch','Clean','Clean and Jerk','Jerk','Front squat','Back squat','Pull','Deadlift','Bench Press','Barbell Row'],b.referenceLift)}</select>`)}${field('Today’s reference max (kg)',`<input type="number" min="1" step="0.5" inputmode="decimal" data-block-field="reference" data-b="${b.id}" value="${esc(b.reference)}">`,'Changes this plan, not your PB.')}</div>
    <div class="studio-grid">${field('Block duration (minutes)',`<input type="number" min="1" data-block-field="minutes" data-b="${b.id}" value="${b.minutes}">`)}${field('Warm-up suggestion',`<select data-block-field="warmups" data-b="${b.id}"><option value="yes" ${b.warmups?'selected':''}>Include build-up</option><option value="no" ${!b.warmups?'selected':''}>Working sets only</option></select>`)}</div>
    <h4>Working stages</h4>${b.stages.map((s,n)=>stageHTML(b,s,n)).join('')}${button('+ Add stage','stage-add',`data-b="${b.id}"`,'wide')}
    <div class="studio-preview" data-preview="${b.id}">${previewHTML(b)}</div></section>`;}
  function stageHTML(b,s,i){return `<div class="studio-stage"><div class="studio-stage-head"><strong>Stage ${i+1}</strong>${button('Remove','stage-remove',`data-b="${b.id}" data-s="${s.id}"`,'quiet')}</div><div class="studio-grid studio-grid-numeric">${field('Sets',`<input type="number" min="1" max="30" data-stage="sets" data-b="${b.id}" data-s="${s.id}" value="${s.sets}">`)}${field('Load',`<div class="studio-load-input"><input type="number" min="1" step="0.5" data-stage="value" data-b="${b.id}" data-s="${s.id}" value="${s.value}"><select aria-label="Percentage or kilograms" data-stage="mode" data-b="${b.id}" data-s="${s.id}">${options([{value:'percent',label:'%'},{value:'kg',label:'kg'}],s.mode)}</select></div>`)}</div>
    ${b.components.map(c=>field(esc(M.name(c))+' reps',`<input type="number" min="1" max="30" data-stage-rep="${c.id}" data-b="${b.id}" data-s="${s.id}" value="${s.reps[c.id]||1}">`)).join('')}</div>`;}
  function previewHTML(b){try{const sets=M.expand(b,w.loading);const work=sets.filter(s=>s.phase==='work'),warm=sets.filter(s=>s.phase==='warmup');const seconds=sets.reduce((n,s)=>n+s.rest+Math.max(25,s.reps.reduce((a,r)=>a+r,0)*5+15),0);return `<strong>${work.length} ${b.rehearsal?'attempts':'working sets'}${warm.length?' + '+warm.length+' warm-ups':''}</strong><small>Approx ${Math.ceil(seconds/60)} min · ${b.rehearsal?'rehearsal recovery '+((b.restSeconds||180)/60)+' min':'suggested rests · your 2:00 cap'}</small>${!b.rehearsal&&seconds>b.minutes*60?'<small>More time needed: add time or reduce sets. Rest will not be squeezed below 30s above 50%.</small>':''}${sets.some(s=>s.loading.limited)?'<small>⚠ Target outside your available setup; the displayed load is limited. Check before starting.</small>':''}${ProgrammeView.rows(sets.map(s=>({label:s.phase==='warmup'?'Warm-up':s.reps.join('+')+' reps',load:s.weight+' kg'+(s.loading.limited?' ⚠':''),detail:s.rest?'rest '+s.rest+'s':'no timed rest'})))}`;}catch{return'Enter the program to preview weights.';}}
  function stepLabel(b,s){if(s.phase==='warmup')return'Warm-up';const attempt=b.stages.find(x=>x.id===s.stageId)?.attempt;return attempt?['Opener','2nd attempt','3rd attempt'][attempt-1]:'Working set';}
  function planHTML(b,currentKey){return `<section class="session-plan" aria-label="Build-up and working-set plan"><div class="session-plan-title"><h3>${esc(M.sequence(b))}</h3><span>Build-up & ${b.rehearsal?'attempts':'working sets'}</span></div><ol class="session-plan-grid">${M.expand(b,w.loading).map(s=>{const done=w.done[s.key],skipped=w.skipped.includes(s.key),current=s.key===currentKey,status=done?'done':skipped?'skipped':current?'current':'upcoming',weight=done?.weight??s.weight,reps=done?.structure?.map(c=>c.reps)||s.reps;return `<li data-plan-key="${esc(s.key)}" data-plan-status="${status}" ${current?'aria-current="step"':''}>${done?`<button type="button" data-act="edit-completed" data-id="${esc(done.id)}" aria-label="Edit completed ${weight} kg set">`:'<div>'}<small>${esc(stepLabel(b,s))}</small><strong>${weight}<span> kg</span></strong><span>${esc(reps.join('+'))} reps</span><em>${done?'✓ Done':skipped?'Skipped':current?'Now':'Planned'}</em>${done?'</button>':'</div>'}</li>`;}).join('')}</ol></section>`;}
  function accessoryButton(){const count=window.AccessoryApp?.linkedCount?.(w.id)||0;return button(count?'View accessories ('+count+')':'+ Accessories for this session','linked-accessories','','wide');}
  function activeHTML(){const next=M.pending(w)[0],total=w.blocks.reduce((n,b)=>n+M.expand(b,w.loading).length,0),count=Object.keys(w.done).length+w.skipped.length;
    if(!next)return `<section class="studio-card"><h3>Session covered</h3><p>${Object.keys(w.done).length} sets logged · ${w.skipped.length} skipped</p>${notesHTML()}${button('Finish session','finish','','primary wide')}</section>${w.blocks.map(b=>planHTML(b,'')).join('')}`;
    const {block:b,set:s}=next,a=w.actuals?.[s.key]||{},nextBlock=w.blocks[w.blocks.indexOf(b)+1];
    return `<div class="studio-progress"><span>${count} / ${total} sets covered</span><span>${w.blocks.indexOf(b)+1} / ${w.blocks.length} lifts</span></div>${planHTML(b,s.key)}
    <section class="studio-current session-record-card"><span class="eyebrow">${s.phase==='warmup'?'WARM-UP':stepLabel(b,s).toUpperCase()} · ${esc(M.sequence(b))}</span>
    <div class="studio-grid studio-grid-numeric session-record-fields ${s.phase!=='warmup'&&b.components.length===1?'session-record-fields-single':''}">${field('Weight (kg)',`<input type="number" inputmode="decimal" step="${w.loading==='competition'?1:2.5}" min="${s.phase==='warmup'?20:w.loading==='competition'?26:20}" data-actual="weight" value="${a.weight??s.weight}">`)}${b.components.map((c,i)=>field(b.components.length>1?esc(M.name(c))+' reps':'Reps',`<input type="number" inputmode="numeric" min="1" max="30" data-actual-rep="${i}" value="${a.reps?.[i]??s.reps[i]}">`)).join('')}${s.phase==='warmup'?'':field('Quality (1–5)',`<select data-actual="quality" aria-label="Technique quality (optional)"><option value="">—</option>${options(['1','2','3','4','5'],String(a.quality||''))}</select>`)}</div>
    <div class="session-rest" data-rest-running ${w.restEnd>Date.now()?'':'hidden'}><span>Rest</span><strong data-clock>Ready</strong>${button('Skip rest','rest-end','','quiet')}</div>
    ${button(s.phase==='warmup'?'Log warm-up':b.rehearsal?'Log attempt':'Log set','complete','','primary wide')}
    <p class="session-rest-hint">${s.rest?'Then rest '+(s.rest<60?s.rest+'s':Math.floor(s.rest/60)+':'+String(s.rest%60).padStart(2,'0')):'No timed rest after this set'}</p>
    <details class="session-set-note" ${a.note?'open':''}><summary>${a.note?'Set note / how it felt':'Add a set note'}</summary>${field('Set notes / how it felt',`<textarea data-actual="note" placeholder="Add a note whenever you need…">${esc(a.note||'')}</textarea>`)}</details>
    <details class="session-loading"><summary>Bar loading · <span data-loading-label>${loadingLabel(a.weight??s.weight,s.phase)}</span></summary><div data-loading-diagram>${plateHTML(a.weight??s.weight,s.phase)}</div></details>
    ${button('Skip this set','skip','','quiet wide')}</section>
    ${nextBlock?`<p class="session-next-lift">Next lift: <strong>${esc(M.sequence(nextBlock))}</strong></p>`:''}
    <p class="studio-status" data-write-status></p>
    ${w.blocks.length>1?`<details class="studio-details"><summary>Other lifts in this session</summary>${w.blocks.filter(x=>x.id!==b.id).map(x=>planHTML(x,'')).join('')}</details>`:''}
    ${accessoryButton()}${notesHTML()}<details class="studio-details"><summary>Session options</summary>${w.type==='opener'?competitionLinkHTML():''}${b.rehearsal?'':field('Change today’s '+b.referenceLift+' reference (kg)',`<input type="number" inputmode="decimal" data-active-ref="${b.id}" value="${b.reference}">`)}<small>Completed sets stay unchanged.</small><label class="studio-check"><input type="checkbox" data-awake ${awake?'checked':''}> Keep screen awake</label></details><div class="session-end-actions">${button('Finish session','finish-early')}${button('Leave','exit','','quiet')}</div>`;
  }
  function loadingLabel(weight,phase){return w.loading==='competition'?(M.load(weight,w.loading,phase).collars?'Competition loading · 5 kg collars included':'Empty-bar warm-up · no collars'):'Gym loading · collar weight ignored';}
  function plateHTML(weight,phase){const p=M.load(weight,w?.loading||'gym',phase);const colors={25:'#c91e36',20:'#2862bb',15:'#d3ad23',10:'#32965f',5:'#eee',2.5:'#555',2:'#2862bb',1.5:'#d3ad23',1:'#32965f',1.25:'#aaa',.5:'#eee'};return `<div class="studio-loading"><div class="studio-bar"><span class="studio-shaft"></span>${p.plates.map(x=>`<span class="studio-plate" style="background:${colors[x]||'#777'};height:${30+x*1.5}px;color:${[5,15,1.25,.5].includes(x)?'#111':'white'}">${x}</span>`).join('')}${p.collars?'<span class="studio-collar">2.5</span>':''}</div><small>One side: ${p.plates.length?p.plates.join(' + '):'empty bar'}${p.collars?' + 2.5 kg collar':''}. Match both sides.</small><small>${p.bar} kg bar${p.collars?' + 5 kg collars':''}${p.limited?' · requested load exceeds this setup':''}</small></div>`;}
  function notesHTML(){return `<details class="studio-details"><summary>Coach cues, session notes & accessories</summary>${field('Coach cues / notes',`<textarea data-w="notes" placeholder="Add or change at any point">${esc(w.notes||'')}</textarea>`)}${field('Accessories (optional)',`<textarea data-w="accessories" placeholder="Circuit or reminder — no need to log each rep">${esc(w.accessories||'')}</textarea>`)}<label class="studio-check"><input type="checkbox" data-w="accessoriesDone" ${w.accessoriesDone?'checked':''}> Accessories completed</label></details>`;}
  function completedHTML(){return `<details class="studio-details"><summary>Recorded sets · ${Object.keys(w.done).length}</summary>${Object.values(w.done).map(e=>`<div class="studio-completed"><span>${esc(e.notes.split('\n')[0])}</span><strong>${e.weight} kg</strong></div>`).join('')}</details>`;}
  function finishedHTML(){return `<section class="studio-card"><h3>Session complete</h3><p>${Object.keys(w.done).length} recorded sets.</p>${notesHTML()}<p data-write-status></p>${accessoryButton()}${button('Repeat this plan','repeat','','primary wide')}${button('Save as template','template-save','','wide')}${button('Back to Train','switch','','quiet wide')}</section>${completedHTML()}`;}
  function componentFor(bid,cid,context){const b=context==='editor'?editor.block:w.blocks.find(b=>b.id===bid);return{b,c:b.components.find(c=>c.id===cid)};}
  function updatePreview(bid){const el=root()?.querySelector(`[data-preview="${bid}"]`),b=w?.blocks.find(b=>b.id===bid);if(el&&b)el.innerHTML=previewHTML(b);}
  function bind(el){el.querySelectorAll('[data-rehearsal-rest]').forEach(input=>input.oninput=()=>{const b=w.blocks.find(b=>b.id===input.dataset.rehearsalRest);b.restSeconds=Number(input.value)*60;save();updatePreview(b.id);});el.querySelectorAll('[data-rehearsal-attempt]').forEach(input=>{
    input.oninput=()=>{const b=w.blocks.find(b=>b.id===input.dataset.b),attempt=Number(input.dataset.rehearsalAttempt),value=Number(input.value);let stage=b.stages.find(s=>s.attempt===attempt);if(input.value===''&&attempt!==1){b.stages=b.stages.filter(s=>s!==stage);}else{if(!stage){stage={...M.stage(b.components),mode:'kg',attempt};b.stages.push(stage);b.stages.sort((a,b)=>a.attempt-b.attempt);}stage.value=value;if(attempt===1)b.reference=value;}save();updatePreview(b.id);};
    input.onchange=()=>{if(input.value!==''){input.value=Math.floor(Number(input.value));input.oninput();}};
  });el.querySelectorAll('[data-act]').forEach(x=>x.onclick=()=>action(x.dataset.act,x.dataset));
    el.querySelectorAll('[data-w]').forEach(x=>x.oninput=()=>{try{w[x.dataset.w]=x.type==='checkbox'?x.checked:x.value;save();refreshTitle();if(x.dataset.w==='loading'){const hint=x.closest('label')?.querySelector('small');if(hint)hint.textContent=loadingHint();w.blocks.forEach(b=>updatePreview(b.id));}}catch(e){fail(e);}});
    el.querySelectorAll('[data-block-field]').forEach(x=>x.oninput=()=>{try{const b=w.blocks.find(b=>b.id===x.dataset.b),f=x.dataset.blockField;b[f]=f==='warmups'?x.value==='yes':['reference','minutes'].includes(f)?Number(x.value):x.value;save();updatePreview(b.id);}catch(e){fail(e);}});
    el.querySelectorAll('[data-stage]').forEach(x=>x.oninput=()=>{try{const b=w.blocks.find(b=>b.id===x.dataset.b),s=b.stages.find(s=>s.id===x.dataset.s);s[x.dataset.stage]=x.dataset.stage==='mode'?x.value:Number(x.value);save();updatePreview(b.id);}catch(e){fail(e);}});
    el.querySelectorAll('[data-stage-rep]').forEach(x=>x.oninput=()=>{try{const b=w.blocks.find(b=>b.id===x.dataset.b),s=b.stages.find(s=>s.id===x.dataset.s);s.reps[x.dataset.stageRep]=Number(x.value);save();updatePreview(b.id);}catch(e){fail(e);}});
    el.querySelectorAll('[data-comp]').forEach(x=>x.onchange=()=>{try{const {b,c}=componentFor(x.dataset.b,x.dataset.c,x.dataset.context);if(x.dataset.comp==='base'){const fresh=M.component(x.value);Object.assign(c,{...fresh,id:c.id});if(x.dataset.context!=='editor')refs(b);persistAndRender(x.dataset.context);}else{c.name=x.value;persist(x.dataset.context);}}catch(e){fail(e);}});
    el.querySelectorAll('[data-actual],[data-actual-rep]').forEach(x=>x.oninput=()=>{try{const next=M.pending(w)[0];w.actuals||={};const a=w.actuals[next.set.key]||={weight:next.set.weight,reps:[...next.set.reps],note:'',quality:''};if(x.dataset.actualRep!==undefined)a.reps[Number(x.dataset.actualRep)]=x.value;else a[x.dataset.actual]=x.value;save();}catch(e){fail(e);}});
    el.querySelectorAll('[data-actual=weight]').forEach(x=>x.onchange=()=>{if(!(Number(x.value)>0))return;const next=M.pending(w)[0];const snapped=M.load(Number(x.value),w.loading,next.set.phase).weight;if(Number(x.value)!==snapped){x.value=snapped;showToast('Nearest load for this setup: '+snapped+' kg','');}w.actuals||={};w.actuals[next.set.key]||={reps:[...next.set.reps]};w.actuals[next.set.key].weight=snapped;save();const diagram=el.querySelector('[data-loading-diagram]'),label=el.querySelector('[data-loading-label]');if(diagram)diagram.innerHTML=plateHTML(snapped,next.set.phase);if(label)label.textContent=loadingLabel(snapped,next.set.phase);});
    el.querySelectorAll('[data-active-ref]').forEach(x=>x.onchange=()=>{if(!(Number(x.value)>0))return;const b=w.blocks.find(b=>b.id===x.dataset.activeRef);b.reference=Number(x.value);save();render();});
    el.querySelectorAll('[data-awake]').forEach(x=>x.onchange=()=>screenAwake(x.checked));}
  function persist(context){if(context!=='editor')save();}
  function persistAndRender(context){if(context==='editor')renderEditor();else{save();render();}}
  function action(act,d={}){try{
    if(act==='link-plan')return linkCompetition();if(act==='unlink-plan'){delete w.competitionLink;save();render();return;}if(act==='open-comp-plan'){switchTab('comp',document.querySelectorAll('#tabs .tab')[3]);switchCompSub('plan');return;}
    if(act==='linked-accessories')return AccessoryApp.open({parentWorkoutId:w.id,date:w.date,session:w.session});if(act==='accessory')return AccessoryApp.open();if(act==='new-class')return create('class');if(act==='new-solo')return create('solo');if(act==='lesson'){const d=makeDialog('1:1 lesson',`<p>Log it afterwards, or follow a plan during the lesson.</p><button class="studio-primary wide" id="lesson-log">Log a lesson set</button><button class="studio-secondary wide" id="lesson-build">Build a lesson workout</button>`);d.querySelector('#lesson-log').onclick=()=>{d.remove();logDialog(null,'1:1 Session');};d.querySelector('#lesson-build').onclick=()=>{d.remove();create('lesson');};return;}if(act==='import')return importDialog();if(act==='opener')return openerDialog();
    if(act==='resume-draft'){const draft=get(HISTORY,[]).find(x=>x.id===d.id);if(draft){archiveDraft();w=M.copy(draft);view='workout';save();render();top();}return;}
    if(act==='resume'){view='workout';render();top();return;}if(act==='switch'){view='home';render();top();return;}
    if(act==='add-block'){w.blocks.push(refs(M.block()));save();render();return;}
    if(act==='remove-block'){w.blocks=w.blocks.filter(b=>b.id!==d.b);save();render();return;}
    if(act.startsWith('component-')||act==='modifier'){
      const b=d.context==='editor'?editor.block:w.blocks.find(b=>b.id===d.b);const index=b.components.findIndex(c=>c.id===d.c),c=b.components[index];
      if(act==='component-add'){const fresh=M.component();b.components.push(fresh);b.stages.forEach(s=>s.reps[fresh.id]=1);}
      if(act==='component-copy'){const fresh={...M.copy(c),id:M.id()};b.components.splice(index+1,0,fresh);b.stages.forEach(s=>s.reps[fresh.id]=s.reps[c.id]||1);}
      if(act==='component-remove'){b.components.splice(index,1);b.stages.forEach(s=>delete s.reps[c.id]);}
      if(act==='component-up'&&index>0)[b.components[index-1],b.components[index]]=[b.components[index],b.components[index-1]];
      if(act==='component-down'&&index<b.components.length-1)[b.components[index+1],b.components[index]]=[b.components[index],b.components[index+1]];
      if(act==='modifier'){if(d.group==='receiving')c.receiving=c.receiving===d.value?'':d.value;else if(d.group==='position')c.position=c.position.includes(d.value)?[]:[d.value];else{c[d.group]||=[];const i=c[d.group].indexOf(d.value);if(i>=0)c[d.group].splice(i,1);else{if(c.base==='Squat'&&['Back','Front','Overhead','Zercher'].includes(d.value))c.technique=c.technique.filter(v=>!['Back','Front','Overhead','Zercher'].includes(v));c[d.group].push(d.value);}}}
      if(d.context!=='editor'&&(!b.reference||M.reference(b)!==b.referenceLift))refs(b);persistAndRender(d.context);return;
    }
    if(act==='stage-add'){const b=w.blocks.find(b=>b.id===d.b),last=b.stages.at(-1);b.stages.push(last?{...M.copy(last),id:M.id()}:M.stage(b.components));save();render();return;}
    if(act==='stage-remove'){const b=w.blocks.find(b=>b.id===d.b);b.stages=b.stages.filter(s=>s.id!==d.s);save();render();return;}
    if(act==='start'){M.validate(w);w.phase='active';save();render();top();return;}
    if(act==='edit-completed'){const entry=getCachedEntries().find(e=>e.id===d.id)||Object.values(w.done).find(e=>e.id===d.id);if(entry)logDialog(entry);return;}
    if(act==='complete')return complete();if(act==='skip'){const next=M.pending(w)[0];w.skipped.push(next.set.key);w.restEnd=0;save();render();top();return;}
    if(act==='rest-end'){w.restEnd=0;save();clock();return;}
    if(act==='finish'||act==='finish-early')return finish();
    if(act==='exit')return exitDialog();
    if(act==='template-save'){if(!w.blocks.length)throw Error('Add a lift before saving a template.');const items=get(TEMPLATES,[]);const t=M.copy(w);delete t.competitionLink;t.blocks.forEach(b=>delete b.rehearsalWarmups);t.id=M.id();t.done={};t.skipped=[];t.phase='setup';t.templateName=t.blocks.map(M.sequence).join(' / ')||M.sessionLabel(t.session);put(TEMPLATES,[t,...items]);showToast('Template saved — find it on Train home','success');return;}
    if(act==='template-delete')return showConfirm('Delete this template?','Completed records are not changed.','Delete',()=>{put(TEMPLATES,get(TEMPLATES,[]).filter(t=>t.id!==d.id));render();});
    if(act==='template-open'||act==='history'){const item=get(act==='history'?HISTORY:TEMPLATES,[]).find(x=>x.id===d.id);if(item)repeat(item);return;}
    if(act==='repeat')return repeat(w);
    if(act==='editor-close')return closeEditor();if(act==='editor-save')return saveEditor();if(act==='editor-delete')return deleteEditor();
    if(act==='backup')return backupFile();if(act==='recover')return CloudBackup.recover();
  }catch(e){fail(e);}}
  function repeat(plan){archiveDraft();w=M.copy(plan);w.id=M.id();w.date=M.date();w.phase='setup';w.done={};w.skipped=[];w.actuals={};w.restEnd=0;w.blocks.forEach(b=>delete b.rehearsalWarmups);if(w.competitionLink)w.competitionLink.signature='';w=M.migrate(w);view='workout';save();render();top();}
  async function complete(){if(busy)return;busy=true;try{const {block:b,set:s}=M.pending(w)[0],a=w.actuals?.[s.key]||{};const e=M.entry(w,b,s,M.load(a.weight??s.weight,w.loading,s.phase).weight,a.reps||s.reps,a.note||'',a.quality);remember(e);PendingLifts.queue('updateEntry',e,AppData.endpoint());w.done[s.key]=e;delete w.actuals?.[s.key];w.restEnd=s.rest?Date.now()+s.rest*1000:0;beeped=false;save();document.activeElement?.blur();render();top();try{getAudioCtx();}catch{}PendingLifts.drain(AppData.endpoint()).then(()=>{fetchAndRender();updateStatus();}).catch(()=>updateStatus());}catch(e){fail(e);}finally{busy=false;}}
  function finish(){w.phase='finished';w.restEnd=0;put(HISTORY,[M.copy(w),...get(HISTORY,[]).filter(x=>x.id!==w.id)]);save();screenAwake(false);render();top();}
  function exitDialog(){const dialog=makeDialog('Leave this session?',`<p>Completed sets are already logged. You can keep the draft to resume later, or discard only the unfinished plan.</p><div class="studio-footer-actions"><button class="studio-primary" id="keep-draft">Keep draft & leave</button><button class="studio-secondary" id="discard-draft">Discard unfinished plan</button></div>`);dialog.querySelector('#keep-draft').onclick=()=>{view='home';screenAwake(false);dialog.close();dialog.remove();render();top();};dialog.querySelector('#discard-draft').onclick=()=>{put(HISTORY,get(HISTORY,[]).filter(x=>x.id!==w.id));w=null;put(KEY,null);view='home';screenAwake(false);dialog.close();dialog.remove();render();top();};}
  function makeDialog(title,body){const dialog=document.createElement('dialog');dialog.className='studio-dialog';dialog.innerHTML=`<div class="studio-dialog-head"><h2>${esc(title)}</h2><button type="button" class="studio-quiet" aria-label="Close">×</button></div>${body}`;document.body.appendChild(dialog);dialog.querySelector('.studio-dialog-head button').onclick=()=>{dialog.close();dialog.remove();};dialog.addEventListener('click',e=>{const r=dialog.getBoundingClientRect();if(e.target===dialog&&(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)){dialog.close();dialog.remove();}});dialog.showModal();return dialog;}
  function legacyComponent(e){return{id:M.id(),base:e.base==='Clean and Jerk'?'Clean':e.base,position:(e.position||[]).map(p=>p==='Hang (unspecified)'?'Hang Above Knee':p),receiving:e.receiving||'',grip:e.grip||[],technique:(e.technique||[]).filter(x=>!['Complex','2-Position'].includes(x)),reps:e.reps||1,cue:''};}
  function logDialog(entry=null,session='Coached Class'){
    editor={entry,session:M.session(entry?.session||session),date:entry?.date||M.date(),weight:entry?.weight||'',sets:entry?.sets||1,note:entry?.structure?.length&&entry.notes?.startsWith(entry.structure.map(c=>`${c.reps} ${M.name(c)}`).join(' + '))?entry.notes.slice(entry.structure.map(c=>`${c.reps} ${M.name(c)}`).join(' + ').length).trim():entry?.notes||'',quality:entry?.quality||'',block:M.block()};
    editor.block.components=entry?.structure?.length?M.copy(entry.structure):entry?.base==='Clean and Jerk'?[{...legacyComponent(entry),base:'Clean',receiving:'',reps:entry.reps||1},{...M.component('Jerk'),receiving:entry.receiving||'Split',reps:entry.reps||1}]:[entry?legacyComponent(entry):M.component()];
    editor.block.stages=[M.stage(editor.block.components)];renderEditor();
  }
  function renderEditor(){document.getElementById('studio-log-dialog')?.remove();const e=editor,b=e.block;const dialog=makeDialog(e.entry?'Edit logged set':'Log a set',`<div class="studio-grid studio-session-fields">${field('Date',`<input type="date" data-editor="date" value="${e.date}">`)}${field('Session',`<select data-editor="session"><option value="">Choose session</option>${options([{value:'Coached Class',label:'Class'},{value:'1:1 Session',label:'1:1'},{value:'Solo',label:'Solo'},...(M.session(e.entry?.session)==='Competition'?[{value:'Competition',label:'Competition'}]:[])],e.session)}</select>`)}</div>${b.components.map((c,i)=>componentHTML(c,b.id,i,b.components.length,'editor')).join('')}${button('+ Add movement to complex','component-add',`data-b="${b.id}" data-context="editor"`,'wide')}<div class="studio-grid studio-grid-numeric">${field('Weight (kg)',`<input type="number" inputmode="decimal" data-editor="weight" value="${e.weight}">`)}${field('Sets',`<input type="number" min="1" data-editor="sets" value="${e.sets}">`)}</div>${b.components.map(c=>field(esc(M.name(c))+' reps',`<input type="number" min="1" max="30" data-editor-rep="${c.id}" value="${c.reps||1}">`)).join('')}${M.isWarmup(e.entry)?'':field('Lift quality / feel (1–5, optional)',`<select data-editor="quality"><option value="">Not rated</option>${options(['1','2','3','4','5'],String(e.quality||''))}</select>`)}${field('Notes / coach cues',`<textarea data-editor="note">${esc(e.note)}</textarea>`)}${button('Save set','editor-save','','primary wide')}${e.entry?button('Delete set','editor-delete','','quiet wide'):''}`);dialog.id='studio-log-dialog';bind(dialog);dialog.querySelectorAll('[data-editor]').forEach(x=>x.oninput=()=>editor[x.dataset.editor]=x.value);dialog.querySelectorAll('[data-editor-rep]').forEach(x=>x.oninput=()=>b.components.find(c=>c.id===x.dataset.editorRep).reps=Number(x.value));}
  function closeEditor(){document.getElementById('studio-log-dialog')?.remove();editor=null;}
  async function saveEditor(){if(busy)return;busy=true;try{const e=editor;if(!e.date)throw Error('Choose a date.');if(!e.session)throw Error('Choose the session type. Blank does not mean Competition.');if(!(e.weight>0)||!Number.isInteger(Number(e.sets))||!(e.sets>0))throw Error('Enter weight and sets.');const tmp=M.blank('solo');tmp.date=e.date;tmp.session=e.session;const b=e.block;b.reference=e.weight;b.referenceLift=M.reference(b);const set={key:'manual',phase:M.isWarmup(e.entry)?'warmup':'work',percent:100};const entry={...e.entry,...M.entry(tmp,b,set,e.weight,b.components.map(c=>c.reps),e.note,e.quality)};entry.id=e.entry?.id||M.id();entry.sets=Number(e.sets);entry.notes=[b.components.map(c=>`${c.reps} ${M.name(c)}`).join(' + '),e.note].filter(Boolean).join('\n');if(e.entry?.workoutId)entry.workoutId=e.entry.workoutId;else delete entry.workoutId;remember(entry);const result=await saveLiftChange('updateEntry',entry);if(result.queued){const doneKey=Object.keys(w?.done||{}).find(key=>w.done[key].id===entry.id);if(doneKey){w.done[doneKey]=M.copy(entry);save();}closeEditor();if(doneKey&&view==='workout')render();renderLog();renderPBs();showToast(result.saved?(AppData.usesDatabase()?'Saved to database':'Saved to spreadsheet'):'Saved on phone · waiting to sync',result.saved?'success':'');}}catch(e){fail(e);}finally{busy=false;}}
  async function deleteEditor(){const e=editor?.entry;if(!e)return;const d=makeDialog('Delete this set?',`<p>The selected entry will be deleted from your connected data store.</p><button id="confirm-delete-set" class="studio-primary wide">Delete set</button>`);d.querySelector('#confirm-delete-set').onclick=async()=>{const result=await saveLiftChange('deleteEntry',e.id);if(result.queued){const doneKey=Object.keys(w?.done||{}).find(key=>w.done[key].id===e.id);if(doneKey){delete w.done[doneKey];if(!w.skipped.includes(doneKey))w.skipped.push(doneKey);save();}d.close();d.remove();closeEditor();if(doneKey&&view==='workout')render();renderLog();renderPBs();}};}
  function openerDialog(){const sunday=new Date();sunday.setDate(sunday.getDate()+(7-sunday.getDay())%7);const rehearsalDate=`${sunday.getFullYear()}-${String(sunday.getMonth()+1).padStart(2,'0')}-${String(sunday.getDate()).padStart(2,'0')}`;let linkedSource=null;const d=makeDialog('Opener rehearsal',`<p>Use competition loading and practise the build-up. This is logged as Solo, not a meet result.</p>${field('Rehearsal date',`<input type="date" id="opener-date" value="${rehearsalDate}">`)}<button class="studio-secondary wide" id="opener-use-plan">Use competition plan</button><label class="studio-check"><input type="checkbox" id="opener-keep-linked"> Keep attempts linked to the competition plan</label><p id="opener-plan-status" role="status">Pull the attempt weights shown in Comp → Plan, or enter your own below.</p>${['Snatch','Clean and Jerk'].map((base,k)=>`<section class="studio-card"><h3>${base}</h3>${[0,1,2].map(i=>field(['Opener','Proposed second (optional)','Proposed third (optional)'][i],`<input type="number" min="26" step="1" data-opener="${k}-${i}" inputmode="decimal">`)).join('')}</section>`).join('')}<p>Warm-ups and recovery are calculated from each opener. Unlink if you want different rehearsal attempts.</p><button class="studio-primary wide" id="build-openers">Build rehearsal</button>`);
    const checkbox=d.querySelector('#opener-keep-linked'),status=d.querySelector('#opener-plan-status');
    function editable(){d.querySelectorAll('[data-opener]').forEach(input=>input.readOnly=checkbox.checked);}
    function usePlan(){try{const source=competitionSource();M.opener({...source.attempts,date:d.querySelector('#opener-date').value});['Snatch','Clean and Jerk'].forEach((base,k)=>source.attempts[base].forEach((value,i)=>d.querySelector(`[data-opener="${k}-${i}"]`).value=value??''));linkedSource=source;checkbox.checked=true;editable();status.textContent='Linked to '+source.name+'. Your rehearsal date stays separate.';return true;}catch(e){checkbox.checked=false;editable();status.textContent='Set both competition openers to at least 26 kg in Comp → Plan. '+e.message;return false;}}
    d.querySelector('#opener-use-plan').onclick=usePlan;checkbox.onchange=()=>{if(checkbox.checked)usePlan();else{editable();status.textContent='Independent rehearsal · competition plan unchanged.';}};
    d.querySelector('#build-openers').onclick=()=>{try{if(checkbox.checked){const latest=competitionSource();if(linkedSource?.date&&linkedSource.date!==latest.date)throw Error('Competition changed. Pull the current plan again.');if(!usePlan())return;}const spec={date:d.querySelector('#opener-date').value};['Snatch','Clean and Jerk'].forEach((base,k)=>spec[base]=[0,1,2].map(i=>Number(d.querySelector(`[data-opener="${k}-${i}"]`).value)||null));const next=M.opener(spec);if(checkbox.checked&&linkedSource)next.competitionLink={date:linkedSource.date,name:linkedSource.name,signature:linkedSource.signature,status:'linked'};archiveDraft();w=next;view='workout';save();d.close();d.remove();render();top();}catch(e){fail(e);}};
  }

  function importDialog(){const d=makeDialog('Photo → editable program',`<p>Read a photo into draft text, check it, then build the movements. Handwriting can need corrections.</p><button type="button" class="studio-secondary wide" id="choose-program-photo">Choose / take a photo</button><input type="file" id="program-photo" accept="image/*" capture="environment" hidden><img id="program-photo-preview" alt="Your program" hidden><button class="studio-secondary wide" id="read-photo" disabled>Read photo on this device</button><p id="ocr-status" aria-live="polite"></p>${field('Check or paste the transcription',`<textarea id="program-text" rows="12" placeholder="A) Snatch pull + hang snatch (20 min)\n1 x 1+2 @ 70\n3 x 1+1 @ 85\n\nB) Clean (20 min)\n3 x 2 @ 75"></textarea>`)}<button class="studio-primary wide" id="build-transcription">Build editable plan</button>`);let file;const photo=d.querySelector('#program-photo');d.querySelector('#choose-program-photo').onclick=()=>photo.click();photo.onchange=()=>{file=photo.files[0];if(!file)return;if(photoURL)URL.revokeObjectURL(photoURL);photoURL=URL.createObjectURL(file);const img=d.querySelector('#program-photo-preview');img.src=photoURL;img.hidden=false;d.querySelector('#read-photo').disabled=false;};
    d.querySelector('#read-photo').onclick=async()=>{const btn=d.querySelector('#read-photo'),status=d.querySelector('#ocr-status');btn.disabled=true;try{status.textContent='Loading photo reader…';if(!window.Tesseract)await new Promise((resolve,reject)=>{const script=document.createElement('script');script.src='https://cdn.jsdelivr.net/npm/tesseract.js@5.1.1/dist/tesseract.min.js';script.onload=resolve;script.onerror=()=>reject(Error('Could not load the photo reader. Try pasting a transcription.'));document.head.appendChild(script);});const result=await Tesseract.recognize(file,'eng',{logger:m=>{if(status.isConnected)status.textContent=m.status+(m.progress?' '+Math.round(m.progress*100)+'%':'');}});if(d.isConnected){d.querySelector('#program-text').value=result.data.text;status.textContent='Review the transcription carefully, especially handwriting, reps and percentages.';}}catch(e){status.textContent=e.message;}finally{btn.disabled=false;}};
    d.querySelector('#build-transcription').onclick=()=>{try{const next=M.parseText(d.querySelector('#program-text').value);next.blocks.forEach(refs);archiveDraft();w=next;view='workout';save();d.close();d.remove();render();top();}catch(e){d.querySelector('#ocr-status').textContent=e.message;}};
  }
  async function screenAwake(on){awake=on;try{if(on){if(!navigator.wakeLock)throw Error();wake=await navigator.wakeLock.request('screen');}else{await wake?.release();wake=null;}}catch{awake=false;showToast('Screen-awake mode unavailable','');}}
  function clock(){if(!w)return;const seconds=Math.max(0,Math.ceil((w.restEnd-Date.now())/1000));document.querySelectorAll('[data-clock]').forEach(el=>el.textContent=seconds?Math.floor(seconds/60)+':'+String(seconds%60).padStart(2,'0'):'Ready');document.querySelectorAll('[data-rest-running]').forEach(el=>el.hidden=!seconds);if(w.restEnd&&seconds===0&&!beeped){beeped=true;try{playTimerSound();}catch{}}}
  function updateStatus(){const n=PendingLifts.list().length;document.querySelectorAll('[data-write-status]').forEach(el=>el.textContent=n?n+' changes saved on phone · syncing':(AppData.endpoint()?(AppData.usesDatabase()?'Recorded sets confirmed in database':'Recorded sets confirmed in spreadsheet'):'Saved on phone · connect your database in Settings'));const status=CloudBackup.status();document.querySelectorAll('[data-cloud-status]').forEach(el=>el.textContent=!status.connected?'Plans saved on this phone. Connect your database in Settings to back them up.':!status.supported?'Plans saved on this phone. Connect Supabase in Settings to enable plan backup.':status.pending?'Plan backup waiting for confirmation.':!status.lastConfirmed?'Plan backup ready · waiting for the first confirmed save.':'Plans backed up'+(status.lastConfirmed?' · '+new Date(status.lastConfirmed).toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'}):''));}
  function backupFile(){const data={format:'barbell-log-backup',version:1,created:new Date().toISOString(),data:{}};for(let i=0;i<localStorage.length;i++){const k=localStorage.key(i);if(k.startsWith('barbell_'))data.data[k]=localStorage.getItem(k);}const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='barbell-backup-'+M.date()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
  async function restoreFile(event){try{const file=event.target.files[0];if(!file)return;if(file.size>8*1024*1024)throw Error('Backup file is too large.');const payload=JSON.parse(await file.text());if(payload.format!=='barbell-log-backup'||payload.version!==1||!payload.data)throw Error('Choose a Barbell Log backup.');const entries=Object.entries(payload.data);if(entries.some(([k,v])=>!k.startsWith('barbell_')||typeof v!=='string'))throw Error('Invalid backup contents.');const jsonKeys=new Set(['barbell_log_v1','barbell_settings_v1','barbell_workout_v3','barbell_templates_v3','barbell_workout_history_v3','barbell_pending_lifts_v1','barbell_planner_v1','barbell_lift_details_v3','barbell_last_entries_v1','barbell_training_v2','barbell_workout_templates_v2','barbell_training_history_v2','barbell_cloud_pending_v3','barbell_accessory_workout_v1','barbell_accessory_templates_v1','barbell_accessory_history_v1','barbell_accessory_records_v1','barbell_before_database_v4']);entries.filter(([k])=>jsonKeys.has(k)).forEach(([,v])=>JSON.parse(v));showConfirm('Restore this file backup?','Back up current data first. This replaces local plans/settings, not database records.','Restore',()=>{const before=new Map(entries.map(([k])=>[k,localStorage.getItem(k)]));try{const queue=PendingLifts.list();entries.forEach(([k,v])=>localStorage.setItem(k,v));const restored=get('barbell_pending_lifts_v1',[]);localStorage.setItem('barbell_pending_lifts_v1',JSON.stringify([...queue,...restored.filter(i=>!queue.some(q=>q.id===i.id))]));if(!payload.data.barbell_cleanup_20261030_v1)localStorage.removeItem('barbell_cleanup_20261030_v1');location.reload();}catch(e){before.forEach((v,k)=>v===null?localStorage.removeItem(k):localStorage.setItem(k,v));fail(e);}});}catch(e){fail(e);}finally{event.target.value='';}}

  function install(){const pane=document.getElementById('pane-planner'),legacy=document.createElement('div');legacy.id='legacy-planner';legacy.hidden=true;while(pane.firstChild)legacy.appendChild(pane.firstChild);pane.appendChild(legacy);pane.appendChild(Object.assign(document.createElement('div'),{id:'training-root'}));load();render();
    document.querySelector('#tabs .tab:nth-child(2) span').textContent='Train';
    window.openLogModal=()=>logDialog();window.openEditModal=id=>{const e=getCachedEntries().find(e=>e.id===id);if(e)logDialog(e);};
    const settings=document.createElement('details');settings.id='backup-settings';settings.className='studio-settings settings-disclosure';settings.innerHTML=`<summary>Backups & export</summary><div class="settings-disclosure-body"><p data-cloud-status role="status"></p><div class="settings-backup-actions">${button('Download full backup','backup','','secondary wide')}${button('Recover saved plans','recover','','secondary wide')}<button type="button" class="studio-secondary wide" id="restore-backup-button">Restore a file backup</button><input type="file" id="restore-file-backup" accept="application/json,.json" hidden><button type="button" class="studio-secondary wide" id="export-lift-csv">Export lift log (CSV)</button></div><details><summary>What is backed up?</summary><p>Lifts, meet results and bodyweight sync to your account as you log them. Plan snapshots preserve workouts, templates, cues and competition planning.</p><p>The downloaded file contains data currently saved on this phone. Refresh data first for the latest history. Keep occasional downloads: snapshots in the same database are not an independent database backup.</p></details></div>`;document.getElementById('pane-settings').appendChild(settings);bind(settings);settings.querySelector('#restore-file-backup').onchange=restoreFile;settings.querySelector('#restore-backup-button').onclick=()=>settings.querySelector('#restore-file-backup').click();document.getElementById('settings-footer').insertAdjacentHTML('beforeend','<p class="settings-version">Version 2026-10-31.24</p>');settings.querySelector('#export-lift-csv').onclick=exportCSV;

    window.TrainingApp={open,render,begin:type=>create(type),recap:()=>logDialog(null,'1:1 Session'),opener:openerDialog};
    window.addEventListener('settingschange',queueCompetitionSync);document.addEventListener('focusout',()=>{if(competitionSyncQueued)setTimeout(queueCompetitionSync,0);});
    window.addEventListener('pendingliftschange',()=>{updateStatus();CloudBackup.changed();});window.addEventListener('cloudbackupchange',updateStatus);window.addEventListener('cloudrestored',()=>{load();render();renderCountdown();});
    document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'){clock();if(awake)screenAwake(true);}});setInterval(clock,500);CloudBackup.connect();updateStatus();
  }
  if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',install);else install();
})();
